  Payments:{description:'Một dòng là một lần thanh toán. Một đơn có thể có nhiều lần thanh toán.',columns:[['payment_id','INT','PRIMARY KEY'],['order_id','INT','NOT NULL'],['payment_date','DATE','NULL'],['payment_status','VARCHAR(20)','NOT NULL'],['payment_amount','DECIMAL(12,2)','NOT NULL']],rows:[[1,1001,'2026-10-01','Succeeded',120],[2,1002,'2026-10-02','Succeeded',200],[3,1004,'2026-10-04','Succeeded',200],[4,1005,null,'Pending',75],[5,1008,'2026-10-08','Succeeded',95]]}
